		public void UpdateAshiatoIcon() {
			if (CurrentZukanInfo.GetStatus == GET_STATUS.GET)
			{
				PokemonParam pokemonParam = CurrentZukanInfo.GetCurrentPokemonParam();
				XLSXContent.UIDatabase.SheetAshiatoIcon ashiatoIconData = UIManager.Instance.GetAshiatoIconData(pokemonParam.GetMonsNo(), pokemonParam.GetFormNo(), pokemonParam.GetSex(), pokemonParam.GetRareType(), false);
				string assetName = ZukanWork.IsShowFootPrintBoth ? ashiatoIconData.BothIconAssetName : ashiatoIconData.SideIconAssetName;
				if (string.IsNullOrEmpty(assetName))
					footprintImage.sprite = null;
				else
					footprintImage.sprite = UIManager.Instance.GetAtlasSprite(SpriteAtlasID.TEXTUREMASS, assetName);
			}
			else
			{
				footprintImage.sprite = null;
			}
			footprintImage.enabled = footprintImage.sprite != null;
		}
