			Pml.MonsNo monsNo = CurrentZukanInfo.MonsNo;
			for (int i = 0; i < languageButtonSelector.GetButtonCount(); i++)
			{
				ZukanLanguageButton button = languageButtonSelector.GetButton(i) as ZukanLanguageButton;
				button.SetIndex(i);
				button.SetActive(ZukanWork.IsLangFlag((uint)monsNo, button.LangId));
			}
			languageButtonSelector.Setup(ZukanWork.SelectLanguageIndex);
		}
		private void OnSelectLanguageButton(global::Dpr.UI.IUIButton button) {
			button.Select();
			ZukanLanguageButton languageButton = button as ZukanLanguageButton;
			if (languageButton == null)
				return;

			ZukanWork.SelectLanguageIndex = languageButton.GetIndex();
			MessageEnumData.MsgLangId langId = languageButton.LangId;
			pokemonInfoButton.ChangeLanguage(langId);
			UpdateTypes(langId);
			for (int i = 0; i < changeLanguageTexts.Length; i++)
				changeLanguageTexts[i].ChangeLanguage(langId);
		}
		private void OnUnSelectLanguageButton(global::Dpr.UI.IUIButton button) {
