		private void UpdateSexType() {
			ZukanInfo.ModelSexType sexType = CurrentZukanInfo.GetCurrentModelSexType();
			if (sexType == ZukanInfo.ModelSexType.Unknown)
			{
				pokemonMaleIconImage.enabled = false;
				pokemonFemaleIconImage.enabled = false;
			}
			else
			{
				pokemonMaleIconImage.enabled = sexType == ZukanInfo.ModelSexType.Male || sexType == ZukanInfo.ModelSexType.Both;
				pokemonFemaleIconImage.enabled = sexType == ZukanInfo.ModelSexType.Female || sexType == ZukanInfo.ModelSexType.Both;
			}
		}
		private void UpdateRareIcon() {
			pokemonRareIconImage.enabled = CurrentZukanInfo.IsRareCurrentModel();
