		}
		private void PlayVoice(global::Pml.PokePara.PokemonParam pokemonParam) {
			XLSXContent.UIDatabase.SheetPokemonVoice voiceData = UIManager.Instance.GetPokemonVoiceData(pokemonParam.GetMonsNo(), pokemonParam.GetFormNo(), pokemonParam.GetSex(), pokemonParam.GetRareType(), pokemonParam.IsEgg(EggCheckType.BOTH_EGG));
			if (string.IsNullOrEmpty(voiceData.WwiseEvent))
				return;

			if (currentVoiceInstance != null)
				currentVoiceInstance.Stop();

			AudioManager.Instance.PostEvent(AK.EVENTS.STOP_VOICE);
			currentVoiceInstance = AudioManager.Instance.PlayVoice(AudioManager.Instance.GetIdByName(voiceData.WwiseEvent), AudioManager.Instance.GetIdByName(voiceData.stopEventId), instance =>
			{
				if (currentVoiceInstance == instance)
					currentVoiceInstance = null;
			});
		}
		public ZukanDescriptionPanel() { }
	}
